"""Decoder for the internal ``trk`` telemetry record format.

A stream consists of frames with a one-byte record type, a little-endian
16-bit payload length, the payload, and a one-byte checksum.  Multibyte
numbers inside payloads are big-endian.
"""

from datetime import datetime, timedelta, timezone


# The three-byte timestamp is a count of minutes from the device epoch.
_EPOCH = datetime(2000, 1, 2, tzinfo=timezone.utc)
_FLAG_NAMES = ((0x01, "low_battery"), (0x02, "recal"), (0x04, "stale"))
_KNOWN_FLAGS = sum(bit for bit, _ in _FLAG_NAMES)


def _flags(value: int) -> list[str]:
    if value & ~_KNOWN_FLAGS:
        raise ValueError(f"unknown flag bits: 0x{value:02x}")
    return [name for bit, name in _FLAG_NAMES if value & bit]


def _decode_sample(payload: bytes) -> dict:
    # version, minutes (u24), reading in thousandths (u24), flags
    if len(payload) != 8:
        raise ValueError("invalid sample payload length")
    if payload[0] != 0:
        raise ValueError(f"unsupported record version: {payload[0]}")

    minutes = int.from_bytes(payload[1:4], "big")
    timestamp = _EPOCH + timedelta(minutes=minutes)
    value = int.from_bytes(payload[4:7], "big") / 1000
    return {
        "type": "sample",
        "ts": timestamp.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "value": value,
        "flags": _flags(payload[7]),
    }


def _decode_batch(payload: bytes) -> dict:
    # version, item count, count * readings in hundredths (u16), flags
    if len(payload) < 3:
        raise ValueError("invalid batch payload length")
    if payload[0] != 0:
        raise ValueError(f"unsupported record version: {payload[0]}")

    count = payload[1]
    if len(payload) != 3 + 2 * count:
        raise ValueError("invalid batch payload length")
    values = [
        int.from_bytes(payload[pos : pos + 2], "big") / 100
        for pos in range(2, 2 + 2 * count, 2)
    ]
    return {"type": "batch", "values": values, "flags": _flags(payload[-1])}


def decode_records(data: bytes) -> list[dict]:
    """Decode all complete, checksum-valid records in *data*.

    ``ValueError`` is raised rather than silently returning a partial decode
    if a frame is cut short or its payload checksum does not match.
    """
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError("data must be bytes-like")
    data = bytes(data)

    records: list[dict] = []
    offset = 0
    while offset < len(data):
        if len(data) - offset < 3:
            raise ValueError("truncated record header")

        record_type = data[offset]
        payload_len = int.from_bytes(data[offset + 1 : offset + 3], "little")
        payload_start = offset + 3
        frame_end = payload_start + payload_len + 1
        if frame_end > len(data):
            raise ValueError("truncated record payload")

        payload = data[payload_start : payload_start + payload_len]
        checksum = data[frame_end - 1]
        calculated = 0
        for byte in payload:
            calculated ^= byte
        if calculated != checksum:
            raise ValueError(
                f"checksum mismatch at offset {offset}: "
                f"expected 0x{checksum:02x}, calculated 0x{calculated:02x}"
            )

        if record_type == 2:
            records.append(_decode_sample(payload))
        elif record_type == 7:
            records.append(_decode_batch(payload))
        else:
            raise ValueError(f"unknown record type {record_type} at offset {offset}")
        offset = frame_end

    return records
PY
